<script setup>import AppShell from'../../Layouts/AppShell.vue';import PageHeader from'../../Components/PageHeader.vue';import UiButton from'../../Components/UiButton.vue';import UiAlert from'../../Components/UiAlert.vue';import{Head,useForm}from'@inertiajs/vue3';const p=defineProps({event:Object});const form=useForm({...p.event});</script><template><AppShell><Head title="Edit event"/><div class="lp-page-narrow"><PageHeader eyebrow="Event settings" :title="event.name" description="Update presentation, privacy and processing preferences."><UiButton variant="secondary" :href="`/groups/${event.id}`">Cancel</UiButton></PageHeader><UiCard class="mt-8"><form class="space-y-5" @submit.prevent="form.put(`/groups/${event.id}`)"><label class="lp-label">Event name<input v-model="form.name" class="field mt-2" required></label><label class="lp-label">Description<textarea v-model="form.description" class="field mt-2 min-h-28"></textarea></label><div class="grid gap-5 md:grid-cols-2"><label class="lp-label">Event type<input v-model="form.event_type" class="field mt-2"></label><label class="lp-label">Event date<input v-model="form.event_date" type="date" class="field mt-2"></label><label class="lp-label">Location<input v-model="form.location" class="field mt-2"></label><label class="lp-label">Privacy<select v-model="form.privacy" class="field mt-2"><option value="private">Private</option><option value="link_only">Invitation only</option><option value="public">Public</option></select></label></div><fieldset class="space-y-3 rounded-xl border border-slate-200 bg-slate-50 p-4 text-sm"><legend class="font-semibold">Delivery controls</legend><label class="flex gap-3"><input v-model="form.face_recognition_enabled" type="checkbox" class="accent-indigo">Consent-led My Photos</label><label class="flex gap-3"><input v-model="form.allow_guest_upload" type="checkbox" class="accent-indigo">Participant uploads</label><label class="flex gap-3"><input v-model="form.watermark_enabled" type="checkbox" class="accent-indigo">Watermark delivery</label></fieldset><UiAlert v-if="Object.keys(form.errors).length" tone="error">Review the highlighted settings.</UiAlert><UiButton type="submit" :loading="form.processing">Save settings</UiButton></form></UiCard></div></AppShell></template>
